#!/usr/bin/env bash
# Prepare the VM for the test suite. Run as root in the VM, after scripts/install.sh.
#   - builds the C fixtures into /usr/libexec/prove-test (root-owned)
#   - writes the allow-list used by the tests (inject-helper, bench tools, keyd)
#   - shortens the consent timeout so negative cases finish quickly
# usage: setup.sh [consent_timeout_ms]
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
timeout_ms="${1:-4000}"
dst=/usr/libexec/prove-test
install -d -m 0755 "$dst"
for src in inject-helper uring-write; do
    gcc -O2 -Wall -o "$dst/$src" "$here/$src.c"
done
gcc -O2 -Wall -shared -fPIC -o "$dst/evil-preload.so" "$here/evil-preload.c"
for b in "$here"/../bench/*.c; do
    [[ -e "$b" ]] || continue
    gcc -O2 -Wall -o "$dst/$(basename "${b%.c}")" "$b"
done
chown -R root:root "$dst"; chmod -R go-w "$dst"

entry() { # name path flags
    [[ -x "$2" ]] || return 0
    printf '[[tool]]\nname   = "%s"\npath   = "%s"\nsha256 = "%s"\nflags  = %s\n\n' \
        "$1" "$2" "$(sha256sum "$2" | cut -d' ' -f1)" "$3"
}
{
    echo "# Generated by tests/fixtures/setup.sh for the test suite."
    entry inject-helper "$dst/inject-helper" '["inject"]'
    entry bench-write "$dst/bench-write" '["inject"]'
    entry bench-latency "$dst/bench-latency" '["inject"]'
    entry bench-register "$dst/bench-register" '["inject"]'
    # Debian installs the keyd binary as keyd.rvaiya.
    entry keyd "$(readlink -f "$(command -v keyd.rvaiya || command -v keyd || echo /nonexistent)")" '["inject", "assistive"]'
} > /etc/prove/allow-inject.toml

sed -i "s/^consent_timeout_ms = .*/consent_timeout_ms = $timeout_ms/" /etc/prove/provd.toml

# keyd: grab every keyboard and remap one unused key, so that it behaves as a real remapper.
install -d /etc/keyd
cat > /etc/keyd/default.conf <<'CONF'
[ids]
*

[main]
capslock = esc
CONF

systemctl restart provd
sleep 1
provectl status | sed -n '/allow-list/,$p'
